WHERE transfer_orders.status > 0

        AND transfer_orders.to_code LIKE CONCAT('%', #{filter.searchText}, '%')


        AND transfer_orders.order_date >= #{filter.dateFrom}


        AND transfer_orders.order_date <= #{filter.dateTo}


        AND transfer_orders.from_location_group_id = #{filter.fromWarehouseId}


        AND transfer_orders.to_location_group_id = #{filter.toWarehouseId}


        AND transfer_orders.status = #{filter.status}


        AND transfer_orders.created_by = #{filter.createdBy}

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        transfer_orders.to_code ASC


LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.sql:
WHERE transfer_orders.status > 0

    AND transfer_orders.order_date >= #{filterByItem.dateFrom}


    AND transfer_orders.order_date <= #{filterByItem.dateTo}


    AND transfer_orders.from_location_group_id = #{filterByItem.fromWarehouseId}


    AND transfer_orders.to_location_group_id = #{filterByItem.toWarehouseId}


    AND transfer_order_details.product_id IN (SELECT id FROM products WHERE pgroup_id = #{filterByItem.productGroupId})


    AND (SELECT parent_id FROM products WHERE id = transfer_order_details.product_id) = #{filterByItem.parentId}


    AND transfer_order_details.product_id = #{filterByItem.productId}


    AND transfer_orders.created_by = #{filterByItem.createBy}

mapper.select:
SELECT IFNULL(products.parent_id, 0) AS parentId, CASE WHEN products.parent_id IS NULL THEN 'No Parent' ELSE CONCAT_WS(' ', parents.code, parents.name) END AS parentName FROM transfer_orders INNER JOIN transfer_order_details ON transfer_orders.id=transfer_order_details.transfer_order_id INNER JOIN products ON products.id = transfer_order_details.product_id LEFT JOIN products AS parents ON products.parent_id = parents.id
GROUP BY products.parent_id
LIMIT #{filterByItem.page}, #{filterByItem.rowsPerPage}

SELECT transfer_orders.id AS id, CONCAT_WS(' ', products.code, products.name) AS productName, SUM(IFNULL((transfer_order_details.qty * transfer_order_details.conversion), 0)) AS qty, products.price_uom_id AS priceUomId, CASE WHEN products.small_val_uom = 1 THEN (SELECT abbr FROM uoms WHERE id = priceUomId) ELSE (SELECT abbr FROM uoms INNER JOIN uom_conversions ON uom_conversions.to_uom_id = uoms.id WHERE from_uom_id = priceUomId AND is_small_uom = 1 AND uom_conversions.is_active = 1 ORDER BY uom_conversions.id DESC LIMIT 1) END AS uom, ((SELECT cost FROM inventory_valuations WHERE is_active = 1 AND pid = transfer_order_details.product_id AND date <= transfer_orders.order_date ORDER BY date DESC, created DESC, id DESC LIMIT 1) / IFNULL(products.small_val_uom, 1)) AS unitCost FROM transfer_orders INNER JOIN transfer_order_details ON transfer_orders.id=transfer_order_details.transfer_order_id INNER JOIN products ON products.id=transfer_order_details.product_id LEFT JOIN location_groups lg_from ON lg_from.id = transfer_orders.from_location_group_id LEFT JOIN location_groups lg_to ON lg_to.id = transfer_orders.to_location_group_id
AND products.parent_id IS NULL
AND products.parent_id = #{parentId}

mapper.sql:
WHERE transfer_orders.status > 0

    AND transfer_orders.order_date >= #{filterByItem.dateFrom}


    AND transfer_orders.order_date <= #{filterByItem.dateTo}


    AND transfer_orders.status = #{filterByItem.status}


    AND transfer_orders.from_location_group_id = #{filterByItem.fromWarehouseId}


    AND transfer_orders.to_location_group_id = #{filterByItem.toWarehouseId}


    AND transfer_order_details.product_id IN
    (SELECT id FROM products WHERE pgroup_id = #{filterByItem.productGroupId})


    AND transfer_order_details.product_id = #{filterByItem.productId}


    AND transfer_orders.created_by = #{filterByItem.createBy}

mapper.select:
SELECT product_id AS parentId, (SELECT CONCAT_WS(' ',code,name) FROM products WHERE id=product_id) AS parentName FROM transfer_orders INNER JOIN transfer_order_details ON transfer_orders.id=transfer_order_details.transfer_order_id
GROUP BY product_id
LIMIT #{filterByItem.page}, #{filterByItem.rowsPerPage}

SELECT SUM(transfer_order_details.qty * transfer_order_details.conversion) FROM transfer_orders INNER JOIN transfer_order_details ON transfer_orders.id=transfer_order_details.transfer_order_id INNER JOIN products ON products.id=transfer_order_details.product_id
AND products.parent_id IS NULL
AND products.parent_id = #{parentId}

SELECT IFNULL(parent.id, 0) AS parentId, CASE WHEN parent.id IS NULL THEN 'No Parent' ELSE CONCAT_WS(' ', parent.code, parent.name) END AS parentName, ((SELECT cost FROM inventory_valuations WHERE is_active = 1 AND pid = transfer_order_details.product_id AND date <= transfer_orders.order_date ORDER BY date DESC, created DESC, id DESC LIMIT 1) / IFNULL(products.small_val_uom, 1)) * SUM((transfer_order_details.qty * transfer_order_details.conversion)) AS totalCost FROM transfer_orders INNER JOIN transfer_order_details ON transfer_orders.id=transfer_order_details.transfer_order_id LEFT JOIN products ON products.parent_id = transfer_order_details.product_id LEFT JOIN products AS parent ON products.parent_id = products.id LEFT JOIN location_groups lg_from ON lg_from.id = transfer_orders.from_location_group_id LEFT JOIN location_groups lg_to ON lg_to.id = transfer_orders.to_location_group_id LEFT JOIN uoms ON uoms.id = transfer_order_details.qty_uom_id
GROUP BY parent.id
LIMIT #{filterByItem.page}, #{filterByItem.rowsPerPage}
